sys_security_acl.script:
answer = false;

// Administrator can view all approval records
if (gs.hasRole('x_2132473_leave_0.admin')) {
    answer = true;
}

// Manager can view approvals assigned to them
else if (gs.hasRole('x_2132473_leave_0.manager')) {
    answer = current.getValue('approver') == getEmployeeId();
}

// Employee can view approvals related to their own requests
else if (gs.hasRole('x_2132473_leave_0.employee')) {

    var requestGR = new GlideRecord(
        'x_2132473_leave_0_leave_request'
    );

    if (requestGR.get(current.getValue('leave_request'))) {
        answer =
            requestGR.getValue('employee') == getEmployeeId();
    }
}

function getEmployeeId() {
    var emp = new GlideRecord(
        'x_2132473_leave_0_employee'
    );

    emp.addQuery('user', gs.getUserID());
    emp.addQuery('active', true);
    emp.setLimit(1);
    emp.query();

    if (emp.next()) {
        return emp.getUniqueValue();
    }

    return '';
}
